  function base64UrlToUint8Array(base64String){const padding='='.repeat((4-base64String.length%4)%4);const base64=(base64String+padding).replace(/-/g,'+').replace(/_/g,'/');const raw=atob(base64);return Uint8Array.from([...raw].map(c=>c.charCodeAt(0)));}
  async function enableBrowserPush(){
    if(!('serviceWorker' in navigator)||!('PushManager' in window)||!('Notification' in window)){toast('Этот браузер не поддерживает Web Push. Доступна лента уведомлений внутри приложения.','error');return;}
    try{const cfg=await api('/api/push/vapid-public');if(!cfg.configured||!cfg.public_key){toast('Push ещё не настроен на сервере: требуется VAPID_PUBLIC_KEY/VAPID_PRIVATE_KEY. Лента уведомлений работает уже сейчас.','error');return;}const permission=await Notification.requestPermission();if(permission!=='granted'){toast('Разрешение на уведомления не выдано.','error');return;}const registration=await navigator.serviceWorker.register('/service-worker.js');let sub=await registration.pushManager.getSubscription();if(!sub)sub=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:base64UrlToUint8Array(cfg.public_key)});const d=await api('/api/push/subscribe',{method:'POST',body:{subscription:sub.toJSON(),platform:'web'}});toast(d.message,'success');}catch(err){toast('Не удалось подключить push: '+err.message,'error');}
  }
